<script nonce="<?= htmlspecialchars(\App\Core\Security::nonce(),ENT_QUOTES,'UTF-8') ?>">
(()=>{const form=document.getElementById('campus-import-form'),check=document.getElementById('check-import'),execute=document.getElementById('execute-import'),review=document.getElementById('import-review'),list=document.getElementById('review-list'),summary=document.getElementById('review-summary'),toggle=document.getElementById('toggle-all'),message=document.getElementById('import-message');let rows=[];const selected=()=>[...list.querySelectorAll('input[type=checkbox]:checked')].map(input=>input.value);const refresh=()=>{const count=selected().length;execute.disabled=count===0;execute.textContent='Importa selezionate ('+count+')';summary.textContent=rows.length+' nuove, '+count+' selezionate';toggle.textContent=count?'Deseleziona tutte':'Seleziona tutte'};const render=items=>{rows=items;list.textContent='';items.forEach(item=>{const label=document.createElement('label');label.className='import-choice'+((item.possible_duplicate||item.realign)?' is-duplicate':'');const input=document.createElement('input');input.type='checkbox';input.value=item.id;input.checked=true;input.addEventListener('change',refresh);const content=document.createElement('span'),name=document.createElement('strong'),details=document.createElement('small');name.textContent='#'+item.id+' — '+item.nome;details.textContent=item.email+' · '+item.evento;content.append(name,details);label.append(input,content);if(item.possible_duplicate||item.realign){const badge=document.createElement('span');badge.className='duplicate-badge';badge.textContent=item.realign?'Correggi associazione corso':'Possibile duplicato';label.appendChild(badge)}list.appendChild(label)});review.hidden=false;message.hidden=true;refresh()};const modeInput=document.getElementById('import-mode'),csvInput=document.getElementById('selected-ids-csv'),frame=document.getElementById('campus-import-target');const send=mode=>{modeInput.value=mode;csvInput.value=mode==='execute'?selected().join(','):'';check.disabled=true;execute.disabled=true;review.hidden=false;message.hidden=false;message.textContent=mode==='check'?'Controllo in corso…':'Importazione in corso…';form.submit()};frame.addEventListener('load',()=>{let result;try{const raw=frame.contentDocument?.body?.innerText||'';if(!raw.trim())return;result=JSON.parse(raw);if(result.errors?.length)throw new Error(result.errors.join(' | '));if(result.mode==='check'){render(Array.isArray(result.to_import)?result.to_import:[]);message.hidden=false;message.textContent=result.to_import?.length?'Controllo completato. Verifica le righe evidenziate e conferma la selezione.':'Nessuna nuova iscrizione da importare.'}else{message.hidden=false;message.textContent='Importazione completata: '+Number(result.imported||0)+' iscrizioni.';execute.disabled=true}check.disabled=false}catch(error){review.hidden=false;message.hidden=false;message.textContent=error instanceof Error?error.message:String(error);check.disabled=false;refresh()}});check.addEventListener('click',()=>{if(form.reportValidity())send('check')});execute.addEventListener('click',()=>send('execute'));toggle.addEventListener('click',()=>{const all=selected().length===0;list.querySelectorAll('input[type=checkbox]').forEach(input=>input.checked=all);refresh()})})();
</script>
